sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	////
    var responseBody;

    try {

        var getPayload = request.body.data;
        var headerContent = getPayload.HEADER;
        var payloadContent = getPayload.PAYLOAD;

        var messageID = getPayload.HEADER.messageid;
        var eventType = getPayload.HEADER.eventtype;
        var sourceType = getPayload.HEADER.source;
        var objID = getPayload.HEADER.objectid;
        var objType = getPayload.HEADER.objecttype;
        var objIDType = getPayload.HEADER.objectidtype;
        var objVersion = getPayload.HEADER.objectversion;
        var eventStatus = getPayload.HEADER.eventstatus;
        var eventDateTime = getPayload.HEADER.eventdatetime;

        // Mandatory Field checks and logging of error if missing or invalid fields 
        if (messageID == '' || messageID == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Message Id'));
			response.setStatus(400);
            return;
        }
        if (eventType == '' || eventType == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Type'));
			response.setStatus(400);
            return;
        }
        if (sourceType == '' || sourceType == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Source'));
			response.setStatus(400);
            return;
        }
        if (objID == '' || objID == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id'));
			response.setStatus(400);
            return;
        }
        if (objType == '' || objType == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Type'));
			response.setStatus(400);
            return;
        }
        if (objIDType == '' || objIDType == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Id Type'));
			response.setStatus(400);
            return;
        }
        if (objVersion == '' || objVersion == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Object Version'));
			response.setStatus(400);
            return;
        }
        if (eventStatus == '' || eventStatus == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Status'));
			response.setStatus(400);
            return;
        }
        if (eventDateTime == '' || eventDateTime == undefined) {
            response.setError(new sn_ws_err.BadRequestError('Missing Event Date Time'));
			response.setStatus(400);
            return;
        }

        if (sourceType == 'TASKIZE' && ( eventType == 'TASKIZE_POLLING' || eventType == 'SYNCH_RESPONSE' )) {
            grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grWidget.addQuery('message_id', messageID);
            grWidget.addQuery('source', sourceType);
            grWidget.query();
            if (grWidget.next()) {
                response.setError(new sn_ws_err.BadRequestError('Duplicate Entry.'));
                response.setStatus(400);
                return;
            } else {
                // Insert new record in the table
                responseBody = new x_hsb11_mss_taskiz.MSSTaskizeUtils().createManualWidgetInboundRecord(headerContent, payloadContent);
            }

        }

        response.setStatus(responseBody.status);
        response.setBody({
            'message': responseBody.message.toString()
        });

    } catch (e) {
        gs.info('Scripted REST API Resource - el_inbound_event_taskize_manual : Unkonwn exception while processing Taskize Manual Request ' + e.message);

        response.setError(new sn_ws_err.BadRequestError(e.message));
        response.setStatus(400);
		return;
    }


})(request, response);
